mapper.select:
SELECT COUNT(*)
FROM student
JOIN room ON room.id=#{roomId}
WHERE student.id=#{studentId}
  AND room.operational_status='ENABLED'
  AND room.gender_restriction=student.gender
  AND (
    (student.student_category='DOMESTIC' AND room.resident_scope IN ('DOMESTIC_ONLY','MIXED'))
    OR (student.student_category='INTERNATIONAL' AND room.resident_scope IN ('INTERNATIONAL_ONLY','MIXED'))
  )
